function AssetUploadModal({modal,close,file,name,setName,modelId,setModelId,models,choose,submit,busy}:Any){
  const [dragging,setDragging]=useState(false);
  const dragDepth=useRef(0);
  useEffect(()=>{if(!modal){dragDepth.current=0;setDragging(false)}},[modal]);
  if(!modal)return null;
  const extension=file?.name?.includes('.')?`.${file.name.split('.').pop()}`:'';
  const dragEnter=(event:Any)=>{event.preventDefault();dragDepth.current+=1;setDragging(true)};
  const dragOver=(event:Any)=>{event.preventDefault();event.dataTransfer.dropEffect='copy'};
  const dragLeave=(event:Any)=>{event.preventDefault();dragDepth.current=Math.max(0,dragDepth.current-1);if(!dragDepth.current)setDragging(false)};
  const drop=(event:Any)=>{event.preventDefault();dragDepth.current=0;setDragging(false);choose(event)};
  return <Modal title="Adicionar asset visual" close={close}><div className="modal-form"><p className="form-help">O ficheiro original será guardado sem conversão. Cada imagem deve ficar associada a um modelo para não criar assets órfãos.</p><label>Modelo associado<select required value={modelId} onChange={e=>setModelId(e.target.value)}><option value="">Seleciona o modelo</option>{models.map((m:Any)=><option key={m.id} value={m.id}>{m.manufacturer} {m.model} · {m.type}</option>)}</select></label><label>Nome do asset<input required value={name} onChange={e=>setName(e.target.value)} placeholder={`ex.: Cisco-C9300-frontal${extension}`}/></label><label className={`upload-dropzone${dragging?' is-dragging':''}`} onDragEnter={dragEnter} onDragOver={dragOver} onDragLeave={dragLeave} onDrop={drop}><Upload size={18}/><strong>{dragging?'Largar imagem aqui':file?'Escolher outro ficheiro':'Escolher imagem'}</strong><small>PNG, JPEG, WebP ou SVG · máximo 10 MB</small><input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden onChange={choose}/></label>{file&&<div className="upload-file-summary"><Upload size={18}/><span><strong>{file.name}</strong><small>{`${(file.size/1024).toFixed(0)} KB · ${file.type || 'imagem'}`}</small></span></div>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={close}>Cancelar</button><button type="button" className="primary-button" disabled={busy||!file||!name.trim()||!modelId} onClick={submit}>{busy?'A guardar…':'Guardar e associar'}</button></div></div></Modal>;
}
function RackEquipmentPreview({rack}:Any){const placed=(rack.devices??[]).filter((device:Any)=>{const start=Number(device.rackUnitStart);const size=Math.max(1,Number(device.rackUnitSize)||1);return Number.isFinite(start)&&start>=1&&start+size-1<=RACK_UNITS});return <span className="rack-preview-overlay-area" aria-hidden="true" style={{left:`${RACK_VIEWPORT.left*100}%`,top:`${RACK_VIEWPORT.top*100}%`,width:`${RACK_VIEWPORT.width*100}%`,height:`${RACK_VIEWPORT.height*100}%`}}>{placed.map((device:Any)=>{const start=Number(device.rackUnitStart);const size=Math.max(1,Number(device.rackUnitSize)||1);const end=start+size-1;const top=((RACK_UNITS-end)/RACK_UNITS)*100;const height=(size/RACK_UNITS)*100;const visual=device.frontAsset||device.model?.frontAsset;return <span className="rack-preview-device" key={device.id} style={{top:`${top}%`,height:`${height}%`}}>{visual?<AssetImage asset={visual} alt=""/>:<EquipmentTypeIcon type={device.type} alt="" className="rack-device-type-icon"/>}</span>})}</span>}
function RackWorkspace({rooms,roomId,racks,selected,setRoom,setRack,onOut,onDevice,onEdit,canEdit}:Any){if(selected)return <RackDetail rack={selected} onOut={onOut} onDevice={onDevice} onEdit={onEdit}/>;return <><section className="ipam-card"><div className="panel-heading"><div><span className="section-kicker">LOCALIZAÇÃO</span><h2>Site → Sala → Bastidores</h2></div></div><div className="room-cards">{rooms.map((r:Any)=><button className={`room-card ${roomId===r.id?'active':''}`} key={r.id} onClick={()=>setRoom(r.id)}><MapPinned size={16}/><span><strong>{r.name}</strong><small>{r.building.name} · {r.racks?.length??0} bastidores</small></span></button>)}</div></section>{roomId&&<section className="ipam-card rack-room-section"><div className="panel-heading"><div><span className="section-kicker">SALA SELECIONADA</span><h2>Bastidores</h2></div>{canEdit&&<button className="primary-button" onClick={()=>onEdit({name:'',room:{id:roomId},roomId})}><Plus size={14}/> Adicionar bastidor</button>}</div><div className="rack-figure-grid">{racks.map((r:Any)=><figure className="rack-figure" key={r.id}><button type="button" className="rack-figure-image" onClick={()=>setRack(r)} aria-label={`Abrir bastidor ${r.name}, ${r.devices?.length??0} equipamentos`}><img src={FIXED_RACK_IMAGE} alt=""/><RackEquipmentPreview rack={r}/></button><figcaption><strong>{r.name}</strong><small>Bastidor padrão · 42U · {r.devices?.length??0} equipamentos</small></figcaption></figure>)}</div>{!racks.length&&<div className="empty-context"><strong>Esta sala ainda não tem bastidores</strong></div>}</section>}</>}
function getNormalizedPortLayoutPorts(device:Any){const configured=device?.model?.portLayout?.ports;if(Array.isArray(configured))return configured;const count=Math.max(0,Number(device?.model?.networkPortCount??device?.model?.portCount??(typeof configured==='number'?configured:0))||0);if(!count)return [];const columns=Math.min(24,Math.max(1,count));const rows=Math.ceil(count/columns);return Array.from({length:count},(_,index)=>({portKey:`ethernet1/${index+1}`,label:`${index+1}`,x:(index%columns+.5)/columns,y:(Math.floor(index/columns)+.5)/rows,width:.8/columns,height:.6/rows}))}
function RackDeviceZoom({deviceId,onBack,onInterfaces,onEditInterface,onEditDevice}:Any){const {apiFetch}=useAuth();const [device,setDevice]=useState<Any>(null);const [loading,setLoading]=useState(true);useEffect(()=>{let live=true;setLoading(true);apiFetch<any>(`/api/v1/devices/${deviceId}`).then(x=>{if(live)setDevice(x)}).catch(()=>{}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[deviceId]);if(loading)return <section className="device-zoom-panel"><span>A carregar equipamento…</span></section>;if(!device)return <section className="device-zoom-panel"><span>Não foi possível carregar o equipamento.</span><button className="secondary-button" onClick={onBack}>Voltar ao bastidor</button></section>;const image=device.frontAsset||device.model?.frontAsset;const interfaces=device.interfaces??[];const ports=getNormalizedPortLayoutPorts(device);const interfaceFor=(p:Any)=>interfaces.find((i:Any)=>i.portKey===p.portKey||i.name===p.portKey);const editPort=(i:Any)=>onEditInterface?onEditInterface(i):onInterfaces(device);return <section className="device-zoom-panel"><div className="device-zoom-header"><div><span className="section-kicker">EQUIPAMENTO SELECIONADO</span><h2>{device.name}</h2><p>{device.hostname||'Sem hostname'} · {device.managementIp||'Sem IP de gestão'}</p></div><div className="button-row"><button className="secondary-button" onClick={onBack}>Voltar ao bastidor</button>{onEditDevice&&<button className="secondary-button" onClick={()=>onEditDevice(device)}><Edit3 size={14}/> Editar equipamento</button>}<button className="primary-button" onClick={()=>onInterfaces(device)}>Abrir ficha completa</button></div></div><div className="device-zoom-grid"><div className="device-zoom-image device-port-stage">{image?<><AssetImage asset={image} alt={`Imagem de ${device.name}`}/>{ports.map((p:Any)=><button key={p.portKey} className={`device-port-hotspot ${interfaceFor(p)?.operUp?'up':''}`} style={{left:`${p.x*100}%`,top:`${p.y*100}%`,width:`${p.width*100}%`,height:`${p.height*100}%`}} onClick={()=>interfaceFor(p)&&editPort(interfaceFor(p))}><span>{p.label}</span><em>{interfaceFor(p)?.name||'não configurada'} · {interfaceFor(p)?.accessVlan?`VLAN ${interfaceFor(p).accessVlan.vlanId}`:'sem VLAN'}</em></button>)}</>:<Server size={42}/>}</div><div className="device-facts"><div><small>Marca / modelo</small><strong>{device.model?`${device.model.manufacturer} · ${device.model.model}`:'Sem modelo'}</strong></div><div><small>Número de série</small><strong>{device.serialNumber||'Não definido'}</strong></div><div><small>Asset tag</small><strong>{device.assetTag||'Não definido'}</strong></div><div><small>Estado</small><strong>{device.status}</strong></div><div><small>U no bastidor</small><strong>{device.rackUnitSize||1}U · posição {device.rackUnitStart||'—'}</strong></div><div><small>Uptime</small><strong>Não disponível — requer agente/SNMP</strong></div></div></div><div className="device-zoom-interfaces"><div className="panel-heading"><h3>Interfaces / portas</h3><span>{interfaces.length} configuradas</span></div>{interfaces.length?<div className="device-interface-grid">{interfaces.map((i:Any)=><button className="device-interface-chip" key={i.id} onClick={()=>editPort(i)}><span className={`port-dot ${i.operUp?'up':''}`}/><strong>{i.name}</strong><small>{i.mode||'sem modo'} · {i.accessVlan?`VLAN ${i.accessVlan.vlanId}`:'sem VLAN'} · {i.accessVlan?.subnets?.[0]?.cidr||'sem subnet'}</small></button>)}</div>:<div className="no-data">Ainda não existem portas configuradas. Abre Interfaces para gerar e configurar as portas.</div>}</div></section>}
function RackEquipmentOverlay({rack,onSelect}:Any){const placed=(rack.devices??[]).filter((device:Any)=>{const start=Number(device.rackUnitStart);const size=Math.max(1,Number(device.rackUnitSize)||1);return Number.isFinite(start)&&start>=1&&start+size-1<=RACK_UNITS});return <div className="rack-overlay-area" style={{left:`${RACK_VIEWPORT.left*100}%`,top:`${RACK_VIEWPORT.top*100}%`,width:`${RACK_VIEWPORT.width*100}%`,height:`${RACK_VIEWPORT.height*100}%`}}>{placed.map((device:Any)=>{const start=Number(device.rackUnitStart);const size=Math.max(1,Number(device.rackUnitSize)||1);const end=start+size-1;const top=((RACK_UNITS-end)/RACK_UNITS)*100;const height=(size/RACK_UNITS)*100;const visual=device.frontAsset||device.model?.frontAsset;return <button type="button" key={device.id} className={`rack-overlay rack-${String(device.type||'other').toLowerCase()}`} style={{top:`${top}%`,height:`${height}%`}} onClick={()=>onSelect(device.id)} aria-label={`Abrir ${device.name}, U${start}${size>1?` a U${end}`:''}`}>
      <span className="rack-device-media">{visual?<AssetImage asset={visual} alt={`Vista frontal de ${device.name}`}/>:<EquipmentTypeIcon type={device.type} alt={`Ícone de ${device.type}`} className="rack-device-type-icon"/>}</span>
      <span className="rack-equipment-tooltip" role="tooltip"><strong>{device.name}</strong><span><small>Localização:</small><b>{rack.name}</b></span><span><small>U:</small><b>{size > 1 ? `U${start}–U${end}` : `U${start}`}</b></span><span><small>IP Management:</small><b>{device.managementIp||'não definido'}</b></span><span><small>Status:</small><b>{String(device.status||'unknown').toLowerCase()}</b></span></span>
    </button>})}</div>}
function RackDetail({rack,onOut,onDevice,onEdit}:Any){const [zoomDeviceId,setZoomDeviceId]=useState('');const hasUnpositioned=(rack.devices??[]).some((device:Any)=>{const start=Number(device.rackUnitStart);const size=Math.max(1,Number(device.rackUnitSize)||1);return !Number.isFinite(start)||start<1||start+size-1>RACK_UNITS});return <section className="ipam-card rack-view"><div className="rack-zoom-toolbar"><button className="secondary-button" onClick={onOut}><ZoomOut size={14}/> Voltar aos bastidores</button><span>{rack.room?.building?.name} / {rack.room?.name} / <strong>{rack.name}</strong></span><button className="secondary-button" onClick={()=>onEdit(rack)}><Edit3 size={14}/> Editar bastidor</button></div>{zoomDeviceId?<RackDeviceZoom deviceId={zoomDeviceId} onBack={()=>setZoomDeviceId('')} onInterfaces={onDevice}/>:<><div className="panel-heading"><div><span className="section-kicker">BASTIDOR VISUAL</span><h2>{rack.name}</h2><p>{rack.devices?.length??0} equipamentos · Bastidor padrão · 42U</p></div></div><div className="rack-stage"><div className="rack-frame"><img src={FIXED_RACK_IMAGE} alt={`Bastidor ${rack.name}`}/><RackEquipmentOverlay rack={rack} onSelect={setZoomDeviceId}/></div></div>{hasUnpositioned&&<div className="no-data">Existem equipamentos por posicionar.</div>}</>}</section>}
function DeviceList({devices,search,onSelect,onEdit,onNew,canEdit}:Any){return <section className="ipam-card"><div className="panel-heading"><div><span className="section-kicker">INVENTÁRIO OPERACIONAL</span><h2>Equipamentos ativos</h2></div>{canEdit&&<button className="primary-button" onClick={onNew}><Plus size={14}/> Adicionar equipamento</button>}</div>{devices.map((d:Any)=><div className="host-row infra-device-row" key={d.id} onClick={()=>onSelect(d)}><span className="host-icon equipment-type-icon-frame"><EquipmentTypeIcon type={d.type}/></span><span><strong>{d.name}</strong><small>{d.type} · {d.model?`${d.model.manufacturer} ${d.model.model}`:'Sem modelo'} · {d.managementIp||'Sem IP de gestão'} · {d.rack?`${d.rack.name} / ${d.rackUnitStart??'?'}U`:'Por localizar'}</small></span><em className="status-active">{d.status}</em>{canEdit&&<button className="icon-button subtle" onClick={e=>{e.stopPropagation();onEdit(d)}}><Edit3 size={14}/></button>}</div>)}{!devices.length&&<div className="empty-context"><Server size={26}/><strong>{search?'Sem equipamentos correspondentes':'Não existem equipamentos ativos neste Site'}</strong></div>}</section>}
function ModelList({models,onEdit,onLayout,canEdit}:Any){const [equipmentType,setEquipmentType]=useState('ALL');const [modelPage,setModelPage]=useState(0);const create=()=>window.dispatchEvent(new Event('model-create-request'));const filteredModels=equipmentType==='ALL'?models:models.filter((model:Any)=>(model.type??'OTHER')===equipmentType);const pageCount=Math.max(1,Math.ceil(filteredModels.length/modelPageSize));const activePage=Math.min(modelPage,pageCount-1);const visibleModels=filteredModels.slice(activePage*modelPageSize,(activePage+1)*modelPageSize);useEffect(()=>setModelPage(current=>Math.min(current,pageCount-1)),[pageCount]);return <section className="ipam-card model-catalog"><div className="panel-heading"><div><span className="section-kicker">CATÁLOGO</span><h2>Modelos</h2></div><div className="model-catalog-toolbar"><label className={`model-type-filter${equipmentType==='ALL'?'':' active'}`}><Filter size={14}/><select aria-label="Filtrar modelos por tipo de equipamento" value={equipmentType} onChange={event=>{setEquipmentType(event.target.value);setModelPage(0)}}><option value="ALL">Todos os tipos</option>{equipmentTypes.map(type=><option key={type} value={type}>{type}</option>)}</select></label>{canEdit&&<button className="primary-button" type="button" onClick={create}><Plus size={14}/> Novo modelo</button>}</div></div>{visibleModels.map((m:Any)=><div className="host-row" key={m.id}><span className="host-icon equipment-type-icon-frame"><EquipmentTypeIcon type={m.type}/></span><span><strong>{m.manufacturer} {m.model}</strong><small>{m.type??'OTHER'} · {Array.isArray(m.portLayout?.ports)?`${m.portLayout.ports.length} portas mapeadas`:'sem portas mapeadas'} · {m.frontAsset?'imagem configurada':'aguarda imagem'}</small></span>{canEdit&&<span className="row-actions"><button className="icon-button subtle" onClick={()=>onEdit(m)}><Edit3 size={14}/></button><button className="secondary-button compact-button map-ports-button" onClick={()=>onLayout(m)}>Mapear portas</button></span>}</div>)}{!filteredModels.length&&<div className="no-data">Não existem modelos para os filtros selecionados.</div>}{filteredModels.length>0&&<div className="model-pagination"><span aria-live="polite"><span key={`${activePage}-${pageCount}`}>{`Página ${activePage+1} de ${pageCount}`}</span></span><div><button type="button" className="icon-button subtle" aria-label="Página anterior" disabled={activePage===0} onClick={()=>setModelPage(activePage-1)}><ChevronLeft size={14}/></button><button type="button" className="icon-button subtle" aria-label="Página seguinte" disabled={activePage>=pageCount-1} onClick={()=>setModelPage(activePage+1)}><ChevronRight size={14}/></button></div></div>}</section>}
function AssetList({assets,onDelete,onUpload,canEdit,canDelete=canEdit}:Any){const upload=onUpload??(()=>window.dispatchEvent(new Event('asset-upload-request')));return <section className="ipam-card"><div className="panel-heading"><div><h2>Assets visuais</h2><p className="form-help">Imagens de frente dos equipamentos usadas no mapeamento de portas.</p></div>{canEdit&&<button className="secondary-button" type="button" onClick={upload}><Upload size={14}/> Importar imagem</button>}</div><div className="asset-grid">{assets.map((a:Any)=><article className="asset-card" key={a.id}><AssetImage asset={a} alt={assetDisplayName(a)}/><strong>{assetDisplayName(a)}</strong><small>{a.mimeType} · {a.license||'Asset interno'}</small>{canDelete&&<button type="button" className="danger-button compact-button" onClick={()=>onDelete(a)}><X size={13}/> Eliminar imagem</button>}</article>)}</div>{!assets.length&&<div className="no-data">Ainda não existem assets visuais. Usa “Importar imagem” para adicionar a primeira imagem.</div>}</section>}
function InterfaceWorkspace({devices,selected,interfaces,selectedInterface,onDevice,onInterface,onGenerate,onEditDevice}:Any){return <section className="ipam-card interfaces-workspace"><div className="panel-heading"><div><span className="section-kicker">PORTAS E CONFIGURAÇÃO</span><h2>Interfaces de rede</h2></div>{selected&&<div className="button-row"><button className="secondary-button" onClick={onGenerate}><Plus size={14}/> Gerar interfaces em falta</button><button className="secondary-button" onClick={onEditDevice}><Edit3 size={14}/> Editar equipamento</button></div>}</div><div className="interface-device-list">{devices.map((d:Any)=><button key={d.id} className={`interface-device ${selected?.id===d.id?'active':''}`} onClick={()=>onDevice(d)}><EquipmentTypeIcon type={d.type} className="interface-device-type-icon"/><span><strong>{d.name}</strong><small>{d.model?`${d.model.manufacturer} ${d.model.model}`:d.type} · {d.managementIp||'sem IP'}</small></span><em>{d.status}</em></button>)}</div>{!selected&&<div className="empty-context"><Layers size={26}/><strong>Seleciona um equipamento</strong><span>Todos os equipamentos ativos com interfaces configuráveis aparecem aqui.</span></div>}{selected&&<div className="interface-detail"><div className="switch-face-container">{selectedModelImage(selected)?<div className="switch-face-image"><AssetImage asset={selectedModelImage(selected)} alt={`Imagem de ${selected.name}`}/>{renderHotspots(selected,interfaces,onInterface)}</div>:<div className="switch-face-fallback"><Server size={28}/><strong>{selected.name}</strong><span>Associa uma imagem e mapeia as portas no modelo.</span></div>}</div><div className="interface-list">{interfaces.map((i:Any)=><InterfaceCard key={i.id} interfaceData={i} selected={selectedInterface?.id===i.id} onEdit={onInterface}/>)}{!interfaces.length&&<div className="no-data">Ainda não existem interfaces. Usa “Gerar interfaces em falta”.</div>}</div></div>}</section>}
function InterfaceCard({interfaceData:i,selected,onEdit}:Any){const open=()=>onEdit(i);return <article className={`interface-row ${selected?'selected':''}`} role="button" tabIndex={0} onClick={open} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}}><span className={`port-dot ${i.operUp?'up':''}`}/><span className="interface-row-summary"><strong>{i.name}</strong><small>{i.interfaceType||'Ethernet'} · {i.mode||'sem modo'} · {i.description||'sem descrição'}</small></span><em>{i.accessVlan?`VLAN ${i.accessVlan.vlanId}`:'sem VLAN'}</em></article>}
function selectedModelImage(device:Any){return device.frontAsset||device.model?.frontAsset}
function renderHotspots(device:Any,interfaces:Any[],onInterface:(i:Any)=>void){return getNormalizedPortLayoutPorts(device).map((p:Any)=><button key={p.portKey} className={`port-hotspot ${interfaces.find(x=>x.portKey===p.portKey||x.name===p.portKey)?.operUp?'up':''}`} style={{left:`${p.x*100}%`,top:`${p.y*100}%`,width:`${p.width*100}%`,height:`${p.height*100}%`}} title={p.label} onClick={()=>{const i=interfaces.find(x=>x.portKey===p.portKey||x.name===p.portKey);if(i)onInterface(i)}}>{p.label}</button>)}

function Editor({modal,close,editingId,form,setForm,rooms,racks,models,assets,vlans,ips,save}:Any){const [vlanSearch,setVlanSearch]=useState('');const visibleVlans=vlans.filter((v:Any)=>`${v.vlanId} ${v.name??''}`.toLowerCase().includes(vlanSearch.trim().toLowerCase()));if(!modal||modal==='layout')return null;if(modal==='device')return <Modal title={editingId?'Gerir equipamento':'Novo equipamento'} close={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();save(editingId?`/api/v1/devices/${editingId}`:'/api/v1/devices',{...form.device,siteId:new URLSearchParams(location.search).get('siteId'),rackId:form.device.rackId||null,rackUnitStart:form.device.rackUnitStart?Number(form.device.rackUnitStart):null,rackUnitSize:Number(form.device.rackUnitSize),modelId:form.device.modelId||null,managementIpAddressId:form.device.managementIpAddressId||null,frontAssetId:form.device.frontAssetId||null})}}><label>Nome<input required value={form.device.name} onChange={e=>setForm.device({...form.device,name:e.target.value})}/></label><div className="form-row"><label>Tipo<select value={form.device.type} onChange={e=>setForm.device({...form.device,type:e.target.value})}>{['SWITCH','ROUTER','FIREWALL','SERVER','STORAGE','OTHER'].map(x=><option key={x}>{x}</option>)}</select></label><label>Estado<select value={form.device.status} onChange={e=>setForm.device({...form.device,status:e.target.value})}>{['UNKNOWN','ACTIVE','INACTIVE','MAINTENANCE','RETIRED'].map(x=><option key={x}>{x}</option>)}</select></label></div><label>Hostname<input value={form.device.hostname} onChange={e=>setForm.device({...form.device,hostname:e.target.value})}/></label><div className="form-row"><label>IP de gestão<input value={form.device.managementIp} onChange={e=>setForm.device({...form.device,managementIp:e.target.value})}/></label><label>IPAM<select value={form.device.managementIpAddressId} onChange={e=>setForm.device({...form.device,managementIpAddressId:e.target.value})}><option value="">Sem associação</option>{ips.map((i:Any)=><option key={i.id} value={i.id}>{i.address} · {i.hostname||'sem hostname'}</option>)}</select></label></div><label>Modelo<select required value={form.device.modelId} onChange={e=>setForm.device({...form.device,modelId:e.target.value})}><option value="">Seleciona um modelo</option>{models.filter((m:Any)=>m.type===form.device.type).map((m:Any)=><option key={m.id} value={m.id}>{m.manufacturer} {m.model}</option>)}</select></label><label>Bastidor<select value={form.device.rackId} onChange={e=>setForm.device({...form.device,rackId:e.target.value})}><option value="">Por localizar</option>{racks.map((r:Any)=><option key={r.id} value={r.id}>{r.room?.name} / {r.name}</option>)}</select></label><div className="form-row"><label>U inicial<input type="number" min="1" value={form.device.rackUnitStart} onChange={e=>setForm.device({...form.device,rackUnitStart:e.target.value})}/></label><label>Tamanho U<input type="number" min="1" value={form.device.rackUnitSize} onChange={e=>setForm.device({...form.device,rackUnitSize:e.target.value})}/></label></div><AssetPicker label="Imagem frontal" value={form.device.frontAssetId} assets={assets} onChange={(v:string)=>setForm.device({...form.device,frontAssetId:v})}/><Actions close={close}/></form></Modal>;
  if(modal==='interface')return <Modal title={`Configurar interface ${form.interface.name}`} close={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();const {id}=form.interface;save(`/api/v1/interfaces/${id}`,{name:form.interface.name,portKey:form.interface.portKey,interfaceType:form.interface.interfaceType,description:form.interface.description,adminUp:form.interface.adminUp,operUp:form.interface.operUp,speedMbps:form.interface.speedMbps?Number(form.interface.speedMbps):undefined,mode:form.interface.mode,nativeVlanId:form.interface.nativeVlanId||undefined,accessVlanId:form.interface.accessVlanId||undefined,allowedVlanIds:form.interface.allowedVlanIds,macAddress:form.interface.macAddress||undefined},'PATCH')}}><label>Nome<input required value={form.interface.name} onChange={e=>setForm.interface({...form.interface,name:e.target.value})}/></label><div className="form-row"><label>Port key<input value={form.interface.portKey} onChange={e=>setForm.interface({...form.interface,portKey:e.target.value})}/></label><label>Tipo<select value={form.interface.interfaceType} onChange={e=>setForm.interface({...form.interface,interfaceType:e.target.value})}>{portTypes.map(x=><option key={x}>{x}</option>)}</select></label></div><label>Descrição<input value={form.interface.description} onChange={e=>setForm.interface({...form.interface,description:e.target.value})}/></label><div className="form-row"><label>Modo<select value={form.interface.mode} onChange={e=>setForm.interface({...form.interface,mode:e.target.value})}><option>ACCESS</option><option>TRUNK</option><option>ROUTED</option></select></label><label>Velocidade Mbps<input type="number" value={form.interface.speedMbps} onChange={e=>setForm.interface({...form.interface,speedMbps:e.target.value})}/></label></div><label>VLAN access<select value={form.interface.accessVlanId} onChange={e=>setForm.interface({...form.interface,accessVlanId:e.target.value})}><option value="">Sem VLAN</option>{vlans.map((v:Any)=><option key={v.id} value={v.id}>VLAN {v.vlanId} · {v.name} {v.subnets?.[0]?`· ${v.subnets[0].cidr}`:'· sem subnet'}</option>)}</select></label><label>VLAN nativa<select value={form.interface.nativeVlanId} onChange={e=>setForm.interface({...form.interface,nativeVlanId:e.target.value})}><option value="">Sem VLAN</option>{vlans.map((v:Any)=><option key={v.id} value={v.id}>VLAN {v.vlanId} · {v.name}</option>)}</select></label><label>VLANs permitidas</label><label className="vlan-search"><Search size={13}/><input aria-label="Pesquisar VLANs" placeholder="Pesquisar VLAN por número ou nome" value={vlanSearch} onChange={e=>setVlanSearch(e.target.value)}/></label><div className="multi-select-list">{visibleVlans.map((v:Any)=><label key={v.id}><input type="checkbox" checked={form.interface.allowedVlanIds.includes(v.id)} onChange={e=>setForm.interface({...form.interface,allowedVlanIds:e.target.checked?[...form.interface.allowedVlanIds,v.id]:form.interface.allowedVlanIds.filter((x:string)=>x!==v.id)})}/><span className="vlan-option-text">{v.vlanId} · {v.name}</span></label>)}{!visibleVlans.length&&<span className="vlan-search-empty">Nenhuma VLAN encontrada.</span>}</div><Actions close={close}/></form></Modal>;
  if(modal==='rack')return <Modal title={editingId?'Editar bastidor':'Novo bastidor'} close={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();save(editingId?`/api/v1/racks/${editingId}`:'/api/v1/racks',{name:form.rack.name,roomId:form.rack.roomId})}}><p className="form-help">Todos os bastidores usam o modelo padrão fixo de 42U.</p><label>Nome<input required value={form.rack.name} onChange={e=>setForm.rack({...form.rack,name:e.target.value})}/></label><label>Sala<select required value={form.rack.roomId} onChange={e=>setForm.rack({...form.rack,roomId:e.target.value})}>{rooms.map((r:Any)=><option key={r.id} value={r.id}>{r.building.name} / {r.name}</option>)}</select></label><Actions close={close}/></form></Modal>;
  return <Modal title={editingId?'Editar modelo':'Novo modelo'} close={close}><form className="modal-form" onSubmit={e=>{e.preventDefault();save(editingId?`/api/v1/device-models/${editingId}`:'/api/v1/device-models',{...form.model,networkPortCount:form.model.networkPortCount?Number(form.model.networkPortCount):null,frontAssetId:form.model.frontAssetId||null})}}><div className="form-row"><label>Fabricante<input required value={form.model.manufacturer} onChange={e=>setForm.model({...form.model,manufacturer:e.target.value})}/></label><label>Modelo<input required value={form.model.model} onChange={e=>setForm.model({...form.model,model:e.target.value})}/></label></div><label>Tipo<select value={form.model.type} onChange={e=>setForm.model({...form.model,type:e.target.value})}>{['SWITCH','ROUTER','FIREWALL','SERVER','STORAGE','OTHER'].map(x=><option key={x}>{x}</option>)}</select></label><label className="checkbox-label"><input type="checkbox" checked={form.model.supportsNetworkPorts} onChange={e=>setForm.model({...form.model,supportsNetworkPorts:e.target.checked})}/> Tem portas de rede configuráveis</label><label>Portas de rede<input type="number" min="1" value={form.model.networkPortCount} onChange={e=>setForm.model({...form.model,networkPortCount:e.target.value})}/></label><AssetPicker label="Imagem frontal" value={form.model.frontAssetId} assets={assets} onChange={(v:string)=>setForm.model({...form.model,frontAssetId:v})}/><Actions close={close}/></form></Modal>;
}

function InteractivePortCanvas({asset,ports,ratio,onUpdate,onDimensions}:Any){const canvas=useRef<HTMLDivElement|null>(null);const interaction=useRef<any>(null);const updateFromPointer=(e:PointerEvent)=>{const active=interaction.current;const element=canvas.current;if(!active||!element)return;const rect=element.getBoundingClientRect();const dx=(e.clientX-active.startX)/rect.width;const dy=(e.clientY-active.startY)/rect.height;const original=active.port;let patch:Any={};if(active.mode==='move'){patch={x:Math.max(0,Math.min(1-original.width,original.x+dx)),y:Math.max(0,Math.min(1-original.height,original.y+dy))}}else{patch={width:Math.max(.005,Math.min(1-original.x,original.width+dx)),height:Math.max(.005,Math.min(1-original.y,original.height+dy))}}onUpdate(active.index,patch)};const stopInteraction=(e:PointerEvent)=>{if(interaction.current&&canvas.current?.hasPointerCapture(e.pointerId))canvas.current.releasePointerCapture(e.pointerId);interaction.current=null};const startInteraction=(e:Any,index:number,mode:'move'|'resize')=>{e.preventDefault();e.stopPropagation();const element=canvas.current;if(!element)return;element.setPointerCapture(e.pointerId);interaction.current={index,mode,startX:e.clientX,startY:e.clientY,port:{...ports[index]}}};return <div ref={canvas} className="port-preview" style={{aspectRatio:ratio}} onPointerMove={updateFromPointer} onPointerUp={stopInteraction} onPointerCancel={stopInteraction}><AssetImage asset={asset} alt="Preview do modelo" onLoad={onDimensions}/>{ports.map((p:Any,i:number)=><span className="port-hotspot-editor" key={`${p.portKey}-${i}`} onPointerDown={e=>startInteraction(e,i,'move')} style={{left:`${p.x*100}%`,top:`${p.y*100}%`,width:`${p.width*100}%`,height:`${p.height*100}%`}} title={`${p.label} · arrastar para mover`}><b>{p.label}</b><i className="port-resize-handle" onPointerDown={e=>startInteraction(e,i,'resize')} title="Redimensionar porta"/></span>)}</div>}
function compactPortGrid(ports:Any[]){const count=ports.length;if(!count)return ports;const columns=Math.min(24,count);const rows=Math.ceil(count/columns);return ports.map((p:Any,index:number)=>({...p,x:.11+((index%columns)+.5)*(.78/columns),y:.33+((Math.floor(index/columns)+.5)*.34/rows),width:.62/columns,height:.24/rows}))}
function PortLayoutEditor({modal,close,layoutModel,layout,setLayout,assets,assetId,setAssetId,detect,confirm,saving,error}:Any){if(!modal)return null;const ports=layout?.ports??[];const updatePort=(index:number,field:string,value:Any)=>setLayout({...layout,ports:ports.map((p:Any,i:number)=>i===index?{...p,[field]:['x','y','width','height'].includes(field)?Number(value):value}:p)});const updateCanvasPort=(index:number,patch:Any)=>setLayout({...layout,ports:ports.map((p:Any,i:number)=>i===index?{...p,...patch}:p)});const addPort=()=>setLayout({...layout,ports:[...ports,{portKey:`ethernet1/${ports.length+1}`,label:`Port ${ports.length+1}`,interfaceType:'ETHERNET',x:.05,y:.05,width:.02,height:.16}]});const removePort=(index:number)=>setLayout({...layout,ports:ports.filter((_:Any,i:number)=>i!==index)});const compactGrid=()=>setLayout({...layout,ports:compactPortGrid(ports),warnings:['Grelha geométrica compacta aplicada; confirma a posição sobre a imagem.']});const ratio=layout?.imageWidth&&layout?.imageHeight?layout.imageWidth/layout.imageHeight:9.32;const captureDimensions=(e:Any)=>setLayout({...layout,imageWidth:e.currentTarget.naturalWidth,imageHeight:e.currentTarget.naturalHeight});const asset=assets.find((a:Any)=>a.id===assetId);return <Modal title={`Mapear portas · ${layoutModel?.manufacturer} ${layoutModel?.model}`} close={close}><div className="port-editor"><p className="form-help">A proposta pode ser revista antes de guardar. Arrasta a porta para mover. Os hotspots começam compactos e podem ser alinhados em grelha.</p>{error&&<div className="ipam-alert error">{error}</div>}<label>Imagem frontal do modelo<select value={assetId} onChange={e=>setAssetId(e.target.value)}><option value="">Seleciona um asset</option>{assets.map((a:Any)=><option key={a.id} value={a.id}>{a.filename}</option>)}</select></label><div className="button-row"><button type="button" className="secondary-button" onClick={detect}><Plus size={14}/> Detetar grelha automaticamente</button><button type="button" className="secondary-button" onClick={compactGrid}>Alinhar e reduzir hotspots</button><button type="button" className="secondary-button" onClick={addPort}><Plus size={14}/> Adicionar porta</button><span className="form-help">Confiança: {layout?.confidence?`${Math.round(layout.confidence*100)}%`:'—'}</span></div>{asset&&<InteractivePortCanvas asset={asset} ports={ports} ratio={ratio} onUpdate={updateCanvasPort} onDimensions={captureDimensions}/>}<div className="port-table">{ports.map((p:Any,i:number)=><div className="port-editor-row" key={`${p.portKey}-${i}`}><input value={p.label??''} onChange={e=>updatePort(i,'label',e.target.value)} placeholder="Nome"/><input value={p.portKey??''} onChange={e=>updatePort(i,'portKey',e.target.value)} placeholder="portKey"/><select value={p.interfaceType??'ETHERNET'} onChange={e=>updatePort(i,'interfaceType',e.target.value)}>{portTypes.map(x=><option key={x}>{x}</option>)}</select><input type="number" step=".001" value={p.x??0} onChange={e=>updatePort(i,'x',e.target.value)} placeholder="x"/><input type="number" step=".001" value={p.y??0} onChange={e=>updatePort(i,'y',e.target.value)} placeholder="y"/><input type="number" step=".001" value={p.width??.02} onChange={e=>updatePort(i,'width',e.target.value)} placeholder="w"/><input type="number" step=".001" value={p.height??.16} onChange={e=>updatePort(i,'height',e.target.value)} placeholder="h"/><button type="button" className="icon-button subtle" onClick={()=>removePort(i)}><X size={14}/></button></div>)}</div><div className="modal-actions"><button type="button" className="secondary-button" onClick={close}>Cancelar</button><button type="button" className="primary-button" onClick={confirm} disabled={saving||!layoutModel||!layout}>{saving?'A guardar…':<><Check size={14}/> Confirmar template</>}</button></div></div></Modal>}
